  function loadJson(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return value??fallback;}catch{return fallback;}}
  function hasCurrentLegalConsent(){return Boolean(legalConsent?.accepted&&legalConsent.termsVersion===TERMS_VERSION&&legalConsent.privacyVersion===PRIVACY_VERSION);}
  function cookieChoiceSaved(){try{if(document.cookie.split(';').some(part=>part.trim()===`${COOKIE_NAME}=essential-only`))return true;const fallback=JSON.parse(localStorage.getItem(COOKIE_FALLBACK_KEY));return fallback?.choice==='essential-only'&&fallback.expiresAt>Date.now();}catch{return false;}}
  function saveCookieChoice(){const path=location.pathname.slice(0,location.pathname.lastIndexOf('/')+1)||'/',secure=location.protocol==='https:'?'; Secure':'';try{document.cookie=`${COOKIE_NAME}=essential-only; Path=${path}; Max-Age=15552000; SameSite=Lax${secure}`;}catch{}try{if(!document.cookie.split(';').some(part=>part.trim()===`${COOKIE_NAME}=essential-only`))localStorage.setItem(COOKIE_FALLBACK_KEY,JSON.stringify({choice:'essential-only',expiresAt:Date.now()+15552000*1000}));}catch{}$('#cookie-notice').classList.add('hidden');if($('#cookie-preferences-dialog').open)$('#cookie-preferences-dialog').close();}
