  function openLegalGate(review=false){const dialog=$('#terms-consent-dialog'),accepted=hasCurrentLegalConsent();$('#terms-consent-checkbox').checked=accepted;$('#terms-consent-accept').disabled=!accepted;$('#terms-consent-accept').textContent=accepted?'Confirmar aceite':'Aceitar e continuar';$('#terms-consent-actions').classList.remove('hidden');$('#terms-consent-declined').classList.add('hidden');$('#terms-consent-cancel').classList.toggle('hidden',!review||!accepted);$('#terms-consent-revoke').hidden=!accepted;$('#terms-consent-revoke').textContent='Revogar meu aceite e sair';if(!dialog.open)dialog.showModal();}
  function acceptLegalTerms(){if(!$('#terms-consent-checkbox').checked)return;legalConsent={accepted:true,termsVersion:TERMS_VERSION,privacyVersion:PRIVACY_VERSION,acceptedAt:new Date().toISOString()};try{localStorage.setItem(LEGAL_CONSENT_KEY,JSON.stringify(legalConsent));}catch{}if($('#terms-consent-dialog').open)$('#terms-consent-dialog').close();renderSettings();showCookieNotice();}
  function declineLegalTerms(){legalConsent=null;try{localStorage.removeItem(LEGAL_CONSENT_KEY);}catch{}$('#terms-consent-checkbox').checked=false;$('#terms-consent-accept').disabled=true;$('#terms-consent-actions').classList.add('hidden');$('#terms-consent-cancel').classList.add('hidden');$('#terms-consent-revoke').hidden=true;$('#terms-consent-declined').classList.remove('hidden');}
