  function makeEvent(data,rng,id,turn){const model=pick(rng,eventModels),city=pick(rng,data.cidades),cityNpcs=data.npcs.filter(n=>n.cidade_id===city.id),npc=cityNpcs.length&&rng()<.45?pick(rng,cityNpcs):null,duration=int(rng,2,6);return{id,tipo:model.tipo,titulo:`${model.titulo} — ${city.nome}`,descricao:model.descricao,impacto:model.impacto,cidade_id:city.id,reino_id:city.reino_id,npc_envolvido_id:npc?.id??null,turno_inicio:turn,duracao_turnos:duration,turno_fim:turn+duration,estado:'ativo'};}
  function advanceTurn(count=1){if(!world)return;const snapshot=JSON.stringify(world);for(let i=0;i<count;i++){world.estado_mundo.turno+=1;const turn=world.estado_mundo.turno;world.eventos.forEach(event=>{if(event.estado==='ativo'&&turn>=event.turno_fim)event.estado='encerrado';});const active=world.eventos.filter(event=>event.estado==='ativo').length;const rng=makeRng(Number(world.metadata.seed||1)+turn*7919);if(active<8&&rng()<.7){let num=world.eventos.length+1,id=`evento-${String(num).padStart(4,'0')}`;while(world.eventos.some(e=>e.id===id)){num++;id=`evento-${String(num).padStart(4,'0')}`;}world.eventos.push(makeEvent(world,rng,id,turn));}}if(!save()){world=JSON.parse(snapshot);const entry=library.worlds.find(item=>item.id===activeWorldId);if(entry)entry.data=world;renderAll();return;}renderAll();toast(`${count} ${count===1?'turno avan\u00e7ado':'turnos avan\u00e7ados'}: agora voc\u00ea est\u00e1 no turno ${world.estado_mundo.turno}.`);}

