    const recent=[...latest,...latestMissions].slice(0,4);
    const activity=`<section class="panel"><div class="panel-header"><div class="panel-title"><span class="panel-title-mark">${icon('chart')}</span>Movimento do mundo</div><button class="text-button" data-view="eventos">Ver eventos ↗</button></div><div class="activity-list">${recent.map(item=>`<div class="activity-row"><span class="activity-icon ${item.tone}">${icon(item.icon)}</span><span class="activity-copy"><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.sub)}</small></span><span class="activity-time">${item.time}</span></div>`).join('')||'<div class="list-empty">Gere alguns eventos para acompanhar o movimento.</div>'}</div></section>`;
    const realmList=world.reinos.slice(0,4).map(r=>`<div class="realm-row"><span class="realm-crest">${escapeHtml(r.nome[0])}</span><span><strong>${escapeHtml(r.nome)}</strong><small>${escapeHtml(r.governo)}</small></span><span class="realm-cities">${r.cidade_ids.length} cidades</span></div>`).join('');
    const realmPanel=`<section class="panel"><div class="panel-header"><div class="panel-title"><span class="panel-title-mark">${icon('globe')}</span>Seus reinos</div><button class="text-button" data-view="reinos">Ver todos ↗</button></div><div class="realm-list">${realmList}</div></section>`;
