  function emptyState(title,description,action='new-world'){return`<div class="empty-state"><div><span class="empty-state-icon">${icon('spark')}</span><h3>${title}</h3><p>${description}</p><button class="button button-primary" data-action="${action}">${icon(action==='import'?'upload':'plus')}${action==='import'?'Importar arquivo':'Começar agora'}</button></div></div>`;}
