  function exportWorld(worldId=activeWorldId){const target=library.worlds.find(entry=>entry.id===worldId)?.data;if(!target){toast('Crie ou importe um mundo antes de exportar.',true);return;}try{validateWorld(target);}catch(error){toast(`N\u00e3o foi poss\u00edvel exportar: ${error.message}`,true);return;}const blob=new Blob([JSON.stringify(target,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${slug(target.metadata.nome)||'mundo'}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup JSON pronto para baixar.');}
