  function exportLibrary(){if(!library.worlds.length){toast('Sua biblioteca ainda est\u00e1 vazia.',true);return;}try{library.worlds.forEach(entry=>validateWorld(entry.data));}catch(error){toast(`N\u00e3o foi poss\u00edvel exportar o backup: ${error.message}`,true);return;}downloadJson({format:'worldforge-library',version:1,exportedAt:new Date().toISOString(),activeWorldId,worlds:library.worlds},'worldforge-biblioteca.json');toast('Backup completo da biblioteca pronto para baixar.');}
