  function importLibraryData(backup){if(!backup||backup.format!=='worldforge-library'||!Array.isArray(backup.worlds)||!backup.worlds.length)throw new Error('O arquivo n\u00e3o cont\u00e9m um backup v\u00e1lido da biblioteca.');for(const entry of backup.worlds){if(!entry||!isWorldData(entry.data))throw new Error('Um dos mundos do backup est\u00e1 inv\u00e1lido.');validateWorld(entry.data);}const seen=new Set(),worlds=backup.worlds.map(entry=>{let id=typeof entry.id==='string'?entry.id:createLibraryId();if(seen.has(id))id=createLibraryId();seen.add(id);const now=new Date().toISOString();return{...entry,id,name:entry.data.metadata.nome,createdAt:entry.createdAt||now,updatedAt:entry.updatedAt||now,data:normalizeWorld(entry.data)};});pendingLibraryBackup={...backup,worlds};$('#library-restore-modal').showModal();}
  function applyLibraryBackup(mode){if(!pendingLibraryBackup)return;const backup=pendingLibraryBackup,imported=backup.worlds,previousLibrary=JSON.stringify(library),previousActiveId=activeWorldId;pendingLibraryBackup=null;$('#library-restore-modal').close();if(mode==='cancel')return;let added=0;if(mode==='replace'){library.worlds=imported;activeWorldId=imported.some(entry=>entry.id===backup.activeWorldId)?backup.activeWorldId:imported[0].id;added=imported.length;}else{const activeBefore=activeWorldId,byId=new Map(library.worlds.map(entry=>[entry.id,entry]));for(const entry of imported){const existing=byId.get(entry.id);if(existing&&JSON.stringify(existing.data)===JSON.stringify(entry.data))continue;if(existing)entry.id=createLibraryId();library.worlds.push(entry);byId.set(entry.id,entry);added++;}activeWorldId=activeBefore||(library.worlds[0]?.id||null);}world=library.worlds.find(entry=>entry.id===activeWorldId)?.data||null;if(!persistLibrary()){library=JSON.parse(previousLibrary);activeWorldId=previousActiveId;world=library.worlds.find(entry=>entry.id===activeWorldId)?.data||null;renderAll();return;}renderAll();setView('inicio');toast(mode==='replace'?'Biblioteca restaurada.':`${added} ${added===1?'mundo foi mesclado':'mundos foram mesclados'} do backup.`);}
  async function readImportFile(file){if(file.size>MAX_IMPORT_BYTES)throw new Error('o arquivo excede o limite de 10 MB.');return file.text();}
  async function handleLibraryImport(file){if(!file)return;try{const backup=JSON.parse(await readImportFile(file));importLibraryData(backup);}catch(error){toast(`Não foi possível restaurar o backup: ${error.message}`,true);}finally{$('#library-import-file').value='';}}
  function importWorld(){if($('#library-modal').open)$('#library-modal').close();$('#import-file').click();}
  async function handleImport(file){if(!file)return;try{const data=JSON.parse(await readImportFile(file));if(data?.format==='worldforge-library'){importLibraryData(data);return;}validateWorld(data);if(!addWorld(data))throw new Error('o armazenamento do navegador nao aceitou o mundo importado.');renderAll();setView('inicio');toast(`${world.metadata.nome} foi importado.`);}catch(error){toast(`Não foi possível importar: ${error.message}`,true);}finally{$('#import-file').value='';}}
